{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const port = Number(process.env.PORT || 8080);
const databasePath = process.env.DB_PATH || './workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
  )
`);
// Upgrade databases created by earlier task checkpoints.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!projectColumns.some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body);
}

const assets = new Map([
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./app.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./styles.css', import.meta.url))]],
]);
const page = readFileSync(new URL('./index.html', import.meta.url));

function sendJson(response, status, data) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(data));
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const archived = url.searchParams.get('filter') === 'Archived' ? 1 : 0;
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived,
        COUNT(t.id) AS totalCount,
        COALESCE(SUM(t.completed), 0) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
    `).all(archived).map((project) => ({ ...project, archived: Boolean(project.archived) }));
    return sendJson(response, 200, projects);
  }
  const projectPath = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectPath && request.method === 'PATCH') {
    let changes;
    try { changes = await readBody(request); } catch {
      return sendJson(response, 400, { error: 'Invalid request body' });
    }
    const projectId = Number(projectPath[1]);
    const project = database.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (typeof changes.archived === 'boolean') {
      database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(changes.archived ? 1 : 0, projectId);
      return sendJson(response, 200, { id: projectId, archived: changes.archived });
    }
    if (typeof changes.name === 'string') {
      const name = changes.name.trim();
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot be renamed' });
      database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
      return sendJson(response, 200, { id: projectId, name });
    }
    if (typeof changes.defaultTaskPriority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(changes.defaultTaskPriority)) return sendJson(response, 400, { error: 'Invalid default task priority' });
      if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot change the default task priority' });
      database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?').run(changes.defaultTaskPriority, projectId);
      return sendJson(response, 200, { id: projectId, defaultTaskPriority: changes.defaultTaskPriority });
    }
    return sendJson(response, 400, { error: 'A project name, default priority, or archive state is required' });
  }
  if (projectPath && request.method === 'GET') {
    const project = database.prepare('SELECT id, name, archived, default_task_priority AS defaultTaskPriority FROM projects WHERE id = ?').get(Number(projectPath[1]));
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, { ...project, archived: Boolean(project.archived) });
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    let name;
    try {
      name = (await readBody(request)).name;
    } catch {
      return sendJson(response, 400, { error: 'Invalid request body' });
    }
    name = typeof name === 'string' ? name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }
  const tasksPath = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksPath && request.method === 'GET') {
    const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id').all(Number(tasksPath[1]));
    return sendJson(response, 200, tasks.map((task) => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksPath && request.method === 'POST') {
    let title;
    try {
      title = (await readBody(request)).title;
    } catch {
      return sendJson(response, 400, { error: 'Invalid request body' });
    }
    title = typeof title === 'string' ? title.trim() : '';
    if (!title) return sendJson(response, 400, { error: 'Task title is required' });
    const projectId = Number(tasksPath[1]);
    const project = database.prepare('SELECT id, default_task_priority AS defaultTaskPriority FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    const result = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)').run(projectId, title, project.defaultTaskPriority);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false, priority: project.defaultTaskPriority });
  }
  const taskPath = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskPath && request.method === 'PATCH') {
    let changes;
    try {
      changes = await readBody(request);
    } catch {
      return sendJson(response, 400, { error: 'Invalid request body' });
    }
    const taskId = Number(taskPath[1]);
    const task = database.prepare(`
      SELECT tasks.id, tasks.project_id AS projectId, tasks.completed, projects.archived
      FROM tasks JOIN projects ON projects.id = tasks.project_id WHERE tasks.id = ?
    `).get(taskId);
    if (!task) return sendJson(response, 404, { error: 'Task not found' });
    if (typeof changes.title === 'string') {
      const title = changes.title.trim();
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      if (task.archived) return sendJson(response, 409, { error: 'Archived projects cannot rename tasks' });
      database.prepare('UPDATE tasks SET title = ? WHERE id = ?').run(title, taskId);
      return sendJson(response, 200, { id: taskId, title, completed: Boolean(task.completed) });
    }
    if (typeof changes.priority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(changes.priority)) return sendJson(response, 400, { error: 'Invalid task priority' });
      if (task.archived) return sendJson(response, 409, { error: 'Archived projects cannot change task priorities' });
      database.prepare('UPDATE tasks SET priority = ? WHERE id = ?').run(changes.priority, taskId);
      return sendJson(response, 200, { id: taskId, priority: changes.priority });
    }
    if (typeof changes.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion must be a boolean' });
    database.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(changes.completed ? 1 : 0, taskId);
    return sendJson(response, 200, { id: taskId, completed: changes.completed });
  }
  if (request.method === 'GET' && assets.has(url.pathname)) {
    const [contentType, content] = assets.get(url.pathname);
    response.writeHead(200, { 'content-type': contentType });
    return response.end(content);
  }
  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return response.end(page);
  }
  sendJson(response, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Workboard listening on 0.0.0.0:${port}`);
});
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectsContainer = document.querySelector('#projects');
const form = document.querySelector('#create-project-form');
const nameInput = document.querySelector('#project-name');
const alertMessage = document.querySelector('#form-alert');
const taskForm = document.querySelector('#create-task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const defaultTaskPriority = document.querySelector('#default-task-priority');
const tasksContainer = document.querySelector('#tasks');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const projectFilter = document.querySelector('#project-filter');
const archiveNotice = document.querySelector('#archive-notice');
const createTaskButton = taskForm.querySelector('button');
const renameForm = document.querySelector('#rename-project-form');
const renameInput = document.querySelector('#new-project-name');
const renameButton = renameForm.querySelector('button');
const renameAlert = document.querySelector('#rename-alert');
let currentProjectId = null;
let currentProjectArchived = false;

async function loadProjects() {
  const response = await fetch(`/api/projects?filter=${encodeURIComponent(projectFilter.value)}`);
  const projects = await response.json();
  projectsContainer.replaceChildren();
  for (const project of projects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => {
      // Each entry from the list starts with the unfiltered task view, even
      // when reopening the project that was just viewed.
      taskFilter.value = 'All';
      priorityFilter.value = 'All';
      navigate(`/projects/${project.id}`);
    });
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    row.append(name, summary, open);
    if (project.archived) {
      const restore = document.createElement('button');
      restore.type = 'button';
      restore.textContent = 'Restore project';
      restore.addEventListener('click', () => setProjectArchived(project.id, false));
      row.append(restore);
    } else {
      const archive = document.createElement('button');
      archive.type = 'button';
      archive.textContent = 'Archive project';
      archive.addEventListener('click', () => setProjectArchived(project.id, true));
      row.append(archive);
    }
    projectsContainer.append(row);
  }
}

async function setProjectArchived(projectId, archived) {
  await fetch(`/api/projects/${projectId}`, {
    method: 'PATCH', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ archived }),
  });
  await loadProjects();
}

async function showRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (!match) {
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
    return;
  }
  const response = await fetch(`/api/projects/${match[1]}`);
  if (!response.ok) {
    navigate('/');
    return;
  }
  const project = await response.json();
  if (currentProjectId !== project.id) {
    taskFilter.value = 'All';
    priorityFilter.value = 'All';
  }
  document.title = `${project.name} · Workboard`;
  document.querySelector('#project-heading').textContent = project.name;
  currentProjectId = project.id;
  currentProjectArchived = project.archived;
  defaultTaskPriority.value = project.defaultTaskPriority;
  defaultTaskPriority.disabled = currentProjectArchived;
  archiveNotice.hidden = !currentProjectArchived;
  renameInput.disabled = currentProjectArchived;
  renameButton.disabled = currentProjectArchived;
  createTaskButton.disabled = currentProjectArchived;
  taskInput.disabled = currentProjectArchived;
  listView.hidden = true;
  detailView.hidden = false;
  await loadTasks();
}

async function loadTasks() {
  if (currentProjectId === null) return;
  const response = await fetch(`/api/projects/${currentProjectId}/tasks`);
  const tasks = await response.json();
  tasksContainer.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'Open' && task.completed) continue;
    if (taskFilter.value === 'Completed' && !task.completed) continue;
    if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = currentProjectArchived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      await fetch(`/api/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ completed: checkbox.checked }),
      });
      await loadTasks();
    });
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority;
    priority.disabled = currentProjectArchived;
    priority.addEventListener('change', async () => {
      const response = await fetch(`/api/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ priority: priority.value }),
      });
      if (response.ok) await loadTasks();
    });
    const renameForm = document.createElement('form');
    renameForm.className = 'task-rename-form';
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.value = task.title;
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.disabled = currentProjectArchived;
    const renameButton = document.createElement('button');
    renameButton.type = 'submit';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = currentProjectArchived;
    const renameAlert = document.createElement('span');
    renameAlert.setAttribute('role', 'alert');
    renameAlert.hidden = true;
    renameForm.append(renameInput, renameButton, renameAlert);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (currentProjectArchived) return;
      const newTitle = renameInput.value.trim();
      if (!newTitle) {
        renameAlert.textContent = 'Task title is required';
        renameAlert.hidden = false;
        return;
      }
      const response = await fetch(`/api/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ title: newTitle }),
      });
      if (response.ok) await loadTasks();
    });
    row.append(title, checkbox, priority, renameForm);
    tasksContainer.append(row);
  }
}

function navigate(path) {
  history.pushState({}, '', path);
  showRoute();
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const name = nameInput.value.trim();
  if (!name) {
    alertMessage.textContent = 'Project name is required';
    alertMessage.hidden = false;
    return;
  }
  const response = await fetch('/api/projects', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!response.ok) return;
  alertMessage.hidden = true;
  nameInput.value = '';
  await loadProjects();
});

document.querySelector('#back-to-projects').addEventListener('click', () => navigate('/'));
renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (currentProjectArchived) return;
  const name = renameInput.value.trim();
  if (!name) {
    renameAlert.textContent = 'Project name is required';
    renameAlert.hidden = false;
    return;
  }
  const response = await fetch(`/api/projects/${currentProjectId}`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!response.ok) return;
  const project = await response.json();
  document.querySelector('#project-heading').textContent = project.name;
  document.title = `${project.name} · Workboard`;
  renameInput.value = '';
  renameAlert.hidden = true;
});
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (currentProjectArchived) return;
  const title = taskInput.value.trim();
  if (!title) {
    taskAlert.textContent = 'Task title is required';
    taskAlert.hidden = false;
    return;
  }
  const response = await fetch(`/api/projects/${currentProjectId}/tasks`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title }),
  });
  if (!response.ok) return;
  taskAlert.hidden = true;
  taskInput.value = '';
  taskFilter.value = 'All';
  await loadTasks();
});
taskFilter.addEventListener('change', loadTasks);
priorityFilter.addEventListener('change', loadTasks);
defaultTaskPriority.addEventListener('change', async () => {
  if (currentProjectId === null || currentProjectArchived) return;
  const response = await fetch(`/api/projects/${currentProjectId}`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ defaultTaskPriority: defaultTaskPriority.value }),
  });
  if (!response.ok) await showRoute();
});
projectFilter.addEventListener('change', loadProjects);
window.addEventListener('popstate', showRoute);
showRoute();
