async function setDate(value) { return fetch("'`${base}/api/tasks/${task.id}`, {method:'"'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({dueDate:value})}); }
if ((await setDate('2024-02-29')).status "'!== 200) throw Error('"'valid leap date rejected');
